"use client";
/* Pip, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Pip(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("pip"); }, []);
  return React.createElement("piix-pal", { "pal": "pip", ...piixAttrs(props) });
}

export default Pip;
